from app.services.sensor_service import SensorServicefrom fastapi import APIRouter, Depends, HTTPExceptionrouter = APIRouter()def get_sensor_service():    return SensorService()@router.get("/reading")def get_reading(service: SensorService = Depends(get_sensor_service)):    data = service.read_value()    if data is None:        raise HTTPException(status_code=503, detail="Lettura sensore non disponibile")    return data